// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.infrastructureimport timber.log.Timberimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.delayimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.withContext/** * NOUS — Thermal Governor (Module 6 v4 — Step 6.7, CRITICAL). * * Mitigates thermal throttling on budget hardware per strategy v4 §"Gap 1: * Thermal Throttling Mitigation Strategy". * * ## Why this matters * * Continuous image processing heats the NPU. Android OS automatically throttles * background threads or camera refresh rate when core temp > 45°C — killing * vision performance without warning. * * ## 4-Tier Adaptive Response (per strategy v4 §"Gap 1") * * | Skin Temp | Tier | Resolution | Color Space | FPS | Engines Active | * |-----------|------|-----------|-------------|-----|----------------| * | < 38°C | NORMAL | 1080p | RGB | 15-20 | All | * | 38-43°C | WARM | 1080p | RGB | 10-15 | All (reduced FPS) | * | 43-48°C | HOT | 720p | Grayscale (OCR only) | 5-10 | SSD + OCR only (Omni-SLM skipped) | * | > 48°C | CRITICAL | Vision suspended | — | 0 | None | * * ## Implementation * * Polls device temperature every 2 seconds via [ThermalProbe]. When the skin * temp crosses a tier boundary, emits a [ThermalState] update via [thermalState] * StateFlow. Other controllers (BatteryAdaptiveController, ObjectDetectionEngine) * observe this flow and adapt their behavior. * * Auto-resumes when temp drops below 43°C (with 5°C hysteresis to prevent flapping). * * ## Testability * * [ThermalProbe] abstracts Android's PowerManager.getThermalService() + * DeviceStateManager. Tests inject [FakeThermalProbe] to simulate any temperature. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Gap 1: Thermal Throttling</a> */class ThermalGovernor(    private val probe: ThermalProbe,    private val pollIntervalMs: Long = DEFAULT_POLL_INTERVAL_MS,    private val hysteresisCelsius: Float = DEFAULT_HYSTERESIS,) {    private val _thermalState = MutableStateFlow(ThermalState.NORMAL)    val thermalState: StateFlow<ThermalState> = _thermalState.asStateFlow()    /** Current skin temperature (°C), or null if unavailable. */    @Volatile    private var currentSkinTemp: Float? = null    /** True if vision is currently suspended due to critical temperature. */    val isVisionSuspended: Boolean        get() = _thermalState.value == ThermalState.CRITICAL    /**     * Start polling the device temperature.     *     * Runs until [stopPolling] is called. Updates [thermalState] on tier changes.     */    suspend fun startPolling(dispatcher: CoroutineDispatcher) = withContext(dispatcher) {        Timber.tag(TAG).i("Thermal polling started (interval=${pollIntervalMs}ms).")        while (true) {            val temp = try {                probe.getSkinTemperatureCelsius()            } catch (t: Throwable) {                Timber.tag(TAG).w("Failed to read temperature — assuming normal.", t)                30f  // Assume normal if probe fails.            }            currentSkinTemp = temp            val newState = classifyTemperature(temp, _thermalState.value)            if (newState != _thermalState.value) {                Timber.tag(TAG).w("Thermal state transition: ${_thermalState.value} → $newState (temp=${temp}°C).")                _thermalState.value = newState            }            delay(pollIntervalMs)        }    }    /**     * Classify temperature into a [ThermalState], with hysteresis to prevent flapping.     *     * Hysteresis: to transition OUT of a higher tier (e.g., HOT → WARM), the     * temperature must drop below the tier's lower bound minus [hysteresisCelsius].     * This prevents rapid oscillation at tier boundaries.     */    internal fun classifyTemperature(tempCelsius: Float, currentState: ThermalState): ThermalState {        return when {            // CRITICAL: > 48°C (or > 43°C with hysteresis from CRITICAL)            tempCelsius > CRITICAL_THRESHOLD ||            (currentState == ThermalState.CRITICAL && tempCelsius > CRITICAL_THRESHOLD - hysteresisCelsius) ->                ThermalState.CRITICAL            // HOT: 43-48°C (or > 38°C with hysteresis from HOT)            tempCelsius > HOT_THRESHOLD ||            (currentState == ThermalState.HOT && tempCelsius > HOT_THRESHOLD - hysteresisCelsius) ->                ThermalState.HOT            // WARM: 38-43°C (or > 33°C with hysteresis from WARM)            tempCelsius > WARM_THRESHOLD ||            (currentState == ThermalState.WARM && tempCelsius > WARM_THRESHOLD - hysteresisCelsius) ->                ThermalState.WARM            // NORMAL: < 38°C            else -> ThermalState.NORMAL        }    }    /**     * Get the adaptive vision configuration for the current thermal state.     *     * Other controllers call this to adapt their behavior:     *  - [ThermalVisionConfig.resolution] — ObjectDetectionEngine downsamples input     *  - [ThermalVisionConfig.targetFps] — MotionGatingController caps FPS     *  - [ThermalVisionConfig.colorSpace] — ImageEnhancementPipeline switches to grayscale     *  - [ThermalVisionConfig.omniSlmEnabled] — ModelManager skips Omni-SLM inference     */    fun getAdaptiveConfig(): ThermalVisionConfig = when (_thermalState.value) {        ThermalState.NORMAL -> ThermalVisionConfig(            resolution = Resolution.FULL_1080P,            colorSpace = ColorSpace.RGB,            targetFps = 20,            omniSlmEnabled = true,            ssdEnabled = true,            ocrEnabled = true,            faceDetectionEnabled = true,        )        ThermalState.WARM -> ThermalVisionConfig(            resolution = Resolution.FULL_1080P,            colorSpace = ColorSpace.RGB,            targetFps = 12,            omniSlmEnabled = true,            ssdEnabled = true,            ocrEnabled = true,            faceDetectionEnabled = false,  // Disable face detection to save heat        )        ThermalState.HOT -> ThermalVisionConfig(            resolution = Resolution.REDUCED_720P,            colorSpace = ColorSpace.GRAYSCALE,            targetFps = 6,            omniSlmEnabled = false,  // Skip Omni-SLM (heaviest engine)            ssdEnabled = true,            ocrEnabled = true,            faceDetectionEnabled = false,        )        ThermalState.CRITICAL -> ThermalVisionConfig(            resolution = Resolution.SUSPENDED,            colorSpace = ColorSpace.SUSPENDED,            targetFps = 0,            omniSlmEnabled = false,            ssdEnabled = false,            ocrEnabled = false,            faceDetectionEnabled = false,        )    }    /** Get the current skin temperature (°C), or null if not yet polled. */    fun getCurrentSkinTemp(): Float? = currentSkinTemp    /** Get the current thermal state. */    fun getCurrentState(): ThermalState = _thermalState.value    private companion object {        private const val TAG = "ThermalGovernor"        private const val DEFAULT_POLL_INTERVAL_MS = 2000L  // 2 seconds        private const val DEFAULT_HYSTERESIS = 5f  // 5°C hysteresis        private const val WARM_THRESHOLD = 38f        private const val HOT_THRESHOLD = 43f        private const val CRITICAL_THRESHOLD = 48f    }}// ──────────────────────────────────────────────────────────────────────────/** Thermal tier (4-level) for adaptive vision response. */enum class ThermalState(val displayName: String, val skinTempRange: String) {    /** < 38°C — all engines active, full resolution. */    NORMAL("Normal", "< 38°C"),    /** 38-43°C — reduced FPS, face detection disabled. */    WARM("Warm", "38-43°C"),    /** 43-48°C — 720p + grayscale + Omni-SLM skipped. */    HOT("Hot", "43-48°C"),    /** > 48°C — vision fully suspended. */    CRITICAL("Critical", "> 48°C");}/** Adaptive vision configuration based on thermal state. */data class ThermalVisionConfig(    val resolution: Resolution,    val colorSpace: ColorSpace,    val targetFps: Int,    val omniSlmEnabled: Boolean,    val ssdEnabled: Boolean,    val ocrEnabled: Boolean,    val faceDetectionEnabled: Boolean,) {    /** True if vision is fully suspended (CRITICAL thermal state). */    val isVisionSuspended: Boolean        get() = resolution == Resolution.SUSPENDED    /** Human-readable user message for this config. */    val userMessage: String        get() = when {            isVisionSuspended -> "Device too hot. Vision paused. Cool down to resume."            !omniSlmEnabled -> "Device hot. Switching to power-saving vision mode."            targetFps < 15 -> "Device warming up. Reducing vision FPS."            else -> ""        }}/** Image resolution tiers. */enum class Resolution(val displayName: String, val width: Int, val height: Int) {    FULL_1080P("1080p", 1920, 1080),    REDUCED_720P("720p", 1280, 720),    SUSPENDED("Suspended", 0, 0);}/** Color space modes. */enum class ColorSpace(val displayName: String) {    RGB("RGB (full color)"),    GRAYSCALE("Grayscale (OCR-optimized)"),    SUSPENDED("Suspended");}// ──────────────────────────────────────────────────────────────────────────/** * Thermal probe interface — abstracts Android thermal APIs. * * Production: [AndroidThermalProbe] uses PowerManager.getThermalService() (API 29+) * or reads /sys/class/thermal/thermal_zoneN/temp (rooted/unrooted fallback). * Tests: [FakeThermalProbe] returns canned temperatures. */interface ThermalProbe {    /** Get the current skin temperature in °C, or null if unavailable. */    suspend fun getSkinTemperatureCelsius(): Float}